// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    // fuzz parameters: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep amount in a practical range but allow zero as well; we want to observe behavior for any input
        vm.assume(depositor != address(0));
        // bound amount to avoid overflow in the test environment for vm.deal
        amount = bound(amount, 0, 1 ether);

        // fund depositor so they can send value
        vm.deal(depositor, amount);

        // depositor adds to balance
        vm.prank(depositor);
        c.addToBalance{value: amount}();

        // sanity: after deposit, getBalance should reflect deposit
        uint256 before = c.getBalance(depositor);
        // allow the case amount == 0; property concerns all inputs including zero
        // Now call withdrawBalance as the depositor
        vm.prank(depositor);
        bool ok;
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): after a successful withdrawBalance call, the reference implementation
        // always sets the caller's recorded balance to zero, so getBalance(depositor) == 0.
        // This will hold for the correct contract for all inputs; the mutant that omits zeroing
        // leaves the balance unchanged and thus will violate this assertion for some inputs.

        // We only assert the property when the withdraw call returned (ok==true). If the withdraw reverted,
        // the state may be unchanged in both versions; the distinguishing behavior is that the reference
        // sets balance to zero on success whereas the mutant does not.
        if (ok) {
            assertTrue(c.getBalance(depositor) == 0);
        } else {
            // If withdraw reverted, still assert that pre-withdraw balance equals post (both should be unchanged):
            // this keeps the property universal on successful calls and avoids false failures on expected reverts.
            assertTrue(c.getBalance(depositor) == before);
        }
    }
}
